/* Focused regression harness for dnsmasq dhcp_netid_list_free().
 *
 * It calls the REAL static functions compiled from src/option.c (exposed via
 * objcopy --globalize-symbol). It reproduces exactly the pointer mutation done
 * by dhcp_reply() in src/rfc2131.c:
 *
 *     for (list = config->netid; list; list = list->next)
 *       { list->list->next = netid; netid = list->list; }
 *
 * i.e. the embedded dhcp_netid->next pointers of a dhcp_netid_list are
 * temporarily repurposed to construct the runtime tag chain, which contains a
 * transient stack node. Freeing such a list with dhcp_netid_free() (which walks
 * ->next) follows those repurposed links and frees non-heap / already-freed
 * memory.
 *
 * Exit status 0 => no invalid free observed (patched behaviour).
 * Non-zero / abort => the vulnerable behaviour was triggered.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct dhcp_netid {
  char *net;
  struct dhcp_netid *next;
};

struct dhcp_netid_list {
  struct dhcp_netid *list;
  struct dhcp_netid_list *next;
};

/* Implemented in src/option.c, made global by the build script. */
extern void dhcp_netid_list_free(struct dhcp_netid_list *netid);

static struct dhcp_netid *mkid(const char *s)
{
  struct dhcp_netid *n = malloc(sizeof(*n));
  n->net = malloc(strlen(s) + 1);
  strcpy(n->net, s);
  n->next = NULL;
  return n;
}

int main(void)
{
  /* config->netid: two set: tags, each list entry holds exactly one netid. */
  struct dhcp_netid_list *a = malloc(sizeof(*a));
  struct dhcp_netid_list *b = malloc(sizeof(*b));
  struct dhcp_netid_list *list;
  struct dhcp_netid *netid;

  /* transient node lives on the stack, as dhcp_reply() does with id/bootp_id. */
  struct dhcp_netid transient;
  transient.net = "bootp"; /* string literal: must never be free()d */
  transient.next = NULL;

  a->list = mkid("setA");
  a->next = b;
  b->list = mkid("setB");
  b->next = NULL;

  netid = &transient;
  for (list = a; list; list = list->next)
    {
      list->list->next = netid;
      netid = list->list;
    }

  /* Config teardown path: clear_dynamic_conf() -> dhcp_config_free(). */
  dhcp_netid_list_free(a);

  printf("OK netid_free_test: transient node intact net=%s\n", transient.net);
  return 0;
}

