/* Positive-path companion to netid_free_test.c:
 * dhcp_netid_free() must keep working for genuine netid chains such as the
 * config->filter (tag:) chain and for the simple list heads freed elsewhere.
 * The candidate patch must not break this.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct dhcp_netid {
  char *net;
  struct dhcp_netid *next;
};

extern void dhcp_netid_free(struct dhcp_netid *nid);

static struct dhcp_netid *mkid(const char *s)
{
  struct dhcp_netid *n = malloc(sizeof(*n));
  n->net = malloc(strlen(s) + 1);
  strcpy(n->net, s);
  n->next = NULL;
  return n;
}

int main(void)
{
  /* genuine two-node chain, as built by dhcp_netid_create(arg+4, new->filter) */
  struct dhcp_netid *a = mkid("tagA");
  struct dhcp_netid *b = mkid("tagB");
  a->next = b;

  dhcp_netid_free(a); /* must free both nodes and both ->net strings */

  printf("OK netid_positive_test: genuine chain freed\n");
  return 0;
}

